    ["note_drop_ifstats_dynamic"] = "Le perdite sono disponibili nell'interfaccia principale",
    ["note_drops_sflow"] = "Le perdite vengono segnalate solo per sFlow poiché il protocollo NetFlow non le riporta.<br>In <A HREF=https://www.ietf.org/rfc/rfc3176.txt>sFlow</A> le perdite indicano il numero di pacchetti che dovevano essere campionati ma che non lo sono stati a causa di risorse insufficienti. Il numero di perdite riportato è riferito all'ultimo reset dell'agent. Un numero alto di perdite indica che l'agent di gestione non è in grado di processare i campioni alla velocità con cui sono generati dall'hardware. Aumentando la frequenza di campionamento sFLow ridurrà la frequenza di perdita dei pacchetti. Nota: un agent che non è in grado d'identificare le perdite riporterà sempre un valore zero.",
    ["note_lifetime_timeout"] = "Indipendentemente dalla durata del flusso, un flusso che è stato attivo per più della <A HREF=https://www.ntop.org/guides/nprobe/cli_options.html?highlight=maximum%20flow%20lifetime>durata</A> massima specificata è considerato scaduto e verrà emesso (opzione nProbe -t)",
    ["note_packets"] = "Nelle reti ethernet, ogni pacchetto ha un <A HREF=\"https://en.wikipedia.org/wiki/Ethernet_frame\">overhead di 24 byte</A> [preambolo (7 bytes), inizio frame (1 byte), CRC (4 bytes), e <A HREF=\"http://en.wikipedia.org/wiki/Interframe_gap\">IFG</A> (12 bytes)]. Di tale overhead bisogna tener conto nel calcolo del traffico dell'interfaccia, ma non nel traffico scambiato tra diversi indirizzo IP. Questo accade poiché tale traffico contribuisce al carico sull'interfaccia, ma non può essere conteggiato come traffico tra gli host, dunque potrebbero esserci discrepanze tra i valori del traffico degli host e quelli dell'interfaccia.",
