    ["dynamic_interfaces_creation_description"] = "ntopng può usare un criterio per diseggregare il traffico in entrata.Quando viene selezionato un criterio di disaggregazione, ntopng utilizzerà il valore del criterio per dividere il traffico in entrata su interfacce create dinamicamente.Per esempio, quando viene selezionato il criterio VLAN Id, verrà creata un'interfaccia dinamica per ogni VLAN Id osservato, ed il traffico in entrata verrà deviato a un'interfaccia dinamica in base al valore del VLAN Id. ",
    ["dynamic_interfaces_creation_note_0"] = "La disaggregazione VLAN Id è supportata sia per le interfacce fisiche che per i flussi ricevuti su ZMQ. Gli altri criteri di disaggregazione sono supportati solo per i flussi ZMQ e saranno inefficaci per le interfacce fisiche.",
    ["dynamic_interfaces_creation_note_1"] = "I cambi di criterio non interesseranno le interfacce esistenti.",
    ["dynamic_interfaces_creation_note_2"] = "Quando si utilizza il criterio sull'Interfaccia d'Ingresso con dispositivi non a flusso, %%INPUT_SNMP deve apparire nel template di nprobe.",
    ["dynamic_interfaces_creation_note_3"] = "Il criterio di disaggregazione 'Interfaccia' aggiunge un flusso a due interfacce dinamiche. Il valore del campo %%INPUT_SNMP è usato per selezionare la prima interfaccia dinamica, mentre il valore di %%OUTPUT_SNMP è usato per selezionare la seconda.",
    ["dynamic_interfaces_creation_note_4"] = "La disaggregazione custom mediante filtri simil-BPF è disponibile anche disabilitando la Disaggregazione Dinamica del Traffico mediante il tab Disaggregazione Custom Del Traffico.",
    ["dynamic_interfaces_creation_title"] = "Criterio Di Disaggregazione",
