    ["toggle_enable_automatic_reports_descr"] = "Attiva/disattiva la generazione di report periodici (giornalieri). I report vengono generati per tutte le interfacce e possono essere disabilitati individualmente nella pagina delle impostazioni dell'interfaccia.",
