    ["toggle_external_auth_captive_portal_description"] = "Autentica e autorizza l'utente utilizzando un servizio esterno in esecuzione nell'URL della pagina informativa. Il servizio esterno deve aggiungere il dispositivo, che non è assegnato per impostazione predefinita, all'utente nEdge appropriato per autorizzarlo.",
    ["toggle_external_auth_captive_portal_title"] = "Autenticazione/autorizzazione esterna",
    ["toggle_fingerprint_stats_description"] = "Abilita le statistiche sulle impronte digitali dell'host locale e il database delle impronte digitali sconosciute (archiviato su redis ntopng.unknown_tcp_fingerprints) utilizzato per migliorare la classificazione.",
