    ["toggle_flow_rrds_description"] = "Abilita la creazione di serie temporali in byte per ogni porta del dispositivo remoto come ricevuta tramite ZMQ (es. sFlow/NetFlow/SNMP).<br>Per dispositivi non sFlow, %%INPUT_SNMP e %%OUTPUT_SNMP devono apparire nel template di nprobe.",
