    ["toggle_host_mask_description"] = "Per motivi di privacy potrebbe essere necessario nascondere gli indirizzi IP degli hosts. Per esempio se sei un ISP non sei autorizzato a conoscere quali indirizzi locali stanno accedendo gli hosts remoti.",
    ["toggle_host_mask_title"] = "Nacondi indirizzi IP host",
