    ["toggle_internals_rrds_title"] = "Internals",
    ["toggle_intranet_traffic_rrds_description"] = "Attiva o disattiva la creazione del traffico di serie temporali tra le reti.<br><b>Nota:</b> queste serie temporali saranno disponibili solo se le serie temporali della rete locale sono abilitate e possono essere trovate nella scheda Serie temporali della rete (ad es. 192.168.2.1/24 -> 172.10.1.1/24).",
    ["toggle_intranet_traffic_rrds_title"] = "Matrice del Traffico di Rete",
