    ["toggle_observation_points_rrds_description"] = "Attiva/disattiva le serie temporali dei punti di osservazione. Non viene creata alcuna serie temporale se non sono presenti punti di osservazione.<br><b>Nota:</b> le preferenze delle applicazioni delle serie temporali L-7 del punto di osservazione sono le stesse dell'interfaccia; quindi se non viene creata alcuna serie temporale per le applicazioni dell'interfaccia L-7, non viene creata alcuna serie temporale per le applicazioni dei punti di osservazione L-7.",
