    ["toggle_search_in_all_interfaces_description"] = "Abilita la ricerca degli host in tutte le interfacce, non solo in quella attualmente selezionata.",
    ["toggle_search_in_all_interfaces_title"] = "Cerca in tutte le interfacce",
    ["toggle_send_telemetry_data_description"] = "Contribuisci al progetto inviando <a href=\"%{url}\">dati di telemetria anonimi</a> crittografati a <a href=\"%{ntop_org}\">ntop.org</a>. I dati riguardano solo lo stato di %{product} (ad esempio, tempo di attività, stato, rapporti sugli arresti anomali). Non verrà mai inviato nulla riguardante il traffico monitorato.",
    ["toggle_send_telemetry_data_title"] = "Telemetria",
    ["toggle_shaping_directions_description"] = "Abilitando questa opzione è possible impostare politiche di shaping differenti per i pachetti d'ingresso e d'uscita.",
    ["toggle_shaping_directions_title"] = "Dividi Le Direzioni dello Shaping",
