    ["toggle_slack_notification_title"] = "Abilita le notifiche di <a href=\"%{url}\">Slack</a>",
    ["toggle_snmp_alerts_port_duplexstatus_change_description"] = "Emetti allarmi quando lo stato duplex di una interfaccia cambia",
