    ["toggle_snmp_alerts_port_errors_title"] = "Allarme sui Contatori Discards/Errori di una Interfaccia",
    ["toggle_snmp_alerts_port_status_change_description"] = "Emetti allarmi generati quando l'Operational State di una Interfaccia cambia.",
    ["toggle_snmp_alerts_port_status_change_title"] = "Allarme sul Cambiamento dell'Operational State di una Interfaccia.",
    ["toggle_snmp_debug_description"] = "Abilita il debugging delle device SNMP. Abilitando questa opzione verranno stampate informazioni aggiuntive nel log di ntopng.",
    ["toggle_snmp_debug_title"] = "Debug SNMP.",
    ["toggle_snmp_excluded_from_usage_description"] = "Per impostazione predefinita, tutte le nuove interfacce/dispositivi verranno aggiunti nella pagina di utilizzo. Abilitando invece questa preferenza, tutte le nuove interfacce/dispositivi verranno esclusi da quella pagina e per includerli nuovamente è necessario modificare la configurazione dell'interfaccia SNMP.",
    ["toggle_snmp_excluded_from_usage_title"] = "Escludi nuove interfacce dall'utilizzo SNMP",
    ["toggle_snmp_polling_description"] = "Attiva/disattiva il polling dei dispositivi SNMP.",
    ["toggle_snmp_polling_title"] = "Polling SNMP",
    ["toggle_snmp_port_admin_status_description"] = "Abilita il cambiamento dell'admin status dell'interfaccia. Il cambiamento è immediato ma il refresh dello stato avverrà durante il prossimo poll.",
    ["toggle_snmp_port_admin_status_title"] = "Admin Status dell'Interfaccia",
    ["toggle_snmp_port_qos_mib_polling_description"] = "Attiva/disattiva il polling QoS MIB dell'interfaccia di un dispositivo.",
    ["toggle_snmp_port_qos_mib_polling_title"] = "Polling MIB QoS dell'interfaccia",
    ["toggle_snmp_rrds_description"] = "Attiva / disattiva la creazione di serie temporali per i bytes di ogni porta dei dispositivi SNMP. Per ogni porta del dispositivoverrà creato un RRD con bytes di ingresso / uscita.",
    ["toggle_snmp_rrds_title"] = "Serie Temporali dei Dispositivi SNMP",
    ["toggle_snmp_trap_description"] = "Attiva/disattiva la raccolta trap SNMP sulla porta UDP:162.",
    ["toggle_snmp_trap_title"] = "Raccolta trap SNMP",
    ["toggle_split_ts_direction_description"] = "Alterna tra la visualizzazione di una singola serie temporale di traffico totale (RX + TX) e di serie temporali separate per RX e TX. Quando è selezionata l'opzione 'Totale' (impostazione predefinita), viene generata una serie temporale combinata. Altrimenti, vengono create serie temporali separate per ciascuna direzione (RX e TX).",
    ["toggle_split_ts_direction_title"] = "Direzioni delle serie temporali divise",
    ["toggle_src_with_post_nat_src_description"] = "Sostituisci gli indirizzi sorgente IPv4(%%IPV4_SRC_ADDR) e le porte (%%L4_SRC_PORT) con i loro valori post-nat (%%POST_NAT_SRC_IPV4_ADDR e %%POST_NAT_SRC_TRANSPORT_PORT).",
    ["toggle_src_with_post_nat_src_title"] = "Usa indirizzi IP Post-Nat e porte IPv4",
    ["toggle_system_probes_timeseries_description"] = "Abilita la creazione di serie temporali per i probe di sistema, quali quello per il monitoraggio dell'RTT o per il monitoraggio di Redis.",
    ["toggle_system_probes_timeseries_title"] = "Probes",
    ["toggle_theme_description"] = "Modifica lo stile di ntopng.",
    ["toggle_theme_title"] = "Tema di ntopng",
    ["toggle_thpt_content_description"] = "Seleziona l'unità di throughput da far vedere nei report del traffico.",
    ["toggle_thpt_content_title"] = "Utità di Throughput",
    ["toggle_tiny_flows_dump_description"] = "Attiva / disattiva l'esportazione dei flussi tiny, ovvero dei flussi con pochi pacchetti o byte.Riduce la cardinalità dei flussi nei database, velocizza l'inserimento e la ricerca. L'ottimizzazione dei flussi tiny può aiutare a limitare la cardinalità del flusso senza ridurre la visibilità delle informazioni salvate.",
    ["toggle_tiny_flows_dump_title"] = "Esporta Flussi Tiny",
    ["toggle_tls_quic_hostnaming_description"] = "Utilizzare lo SNI TLS/QUIC richiesto come nome host. Abilitarla rende la denominazione host più efficace, ma può introdurre falsi positivi nei nomi host.",
    ["toggle_tls_quic_hostnaming_title"] = "Nomi host TLS e QUIC",
    ["toggle_toggle_starttls_description"] = "Abilita l'uso di STARTTLS quando si tenta di connettersi al server di posta elettronica.",
    ["toggle_toggle_starttls_title"] = "Abilita STARTTLS",
    ["toggle_top_sites_description"] = "Attiva / disattiva la creazione dei siti Web più visitati per gli host locali. I top siti sono creati usando <a href=\"%{url}\">un' euristica</a> che mantiene non più di 20 siti per host locale. L'euristica funziona completamente in memoria e non richiede alcuna interazione con il disco. I siti principali vengono cancellati ogni 5 minuti. È possibile creare un archivio storico dei siti Web più visitati, per ciascun host locale, effettuando periodicamente il polling del <i class=\"fas fa-download fa-sm\"></i> download link del JSON accessibile dalla pagina dei dettagli host.",
    ["toggle_top_sites_title"] = "Top Siti HTTP",
    ["toggle_traffic_rrd_creation_description"] = "Abilita la creazione delle serie temporali per bytes e pacchetti.",
    ["toggle_traffic_rrd_creation_title"] = "Traffico",
    ["toggle_use_host_pools_for_local_description"] = "Contrassegna come host locali tutti gli host appartenenti a qualsiasi pool di host diverso dal pool predefinito, indipendentemente dalle reti locali configurate. È necessario un riavvio di ntopng per aggiornare tutti gli host attivi.",
    ["toggle_use_host_pools_for_local_title"] = "Utilizza pool di host per il rilevamento host locale",
    ["toggle_use_mac_in_flow_key_description"] = "Utilizzare l'indirizzo MAC per generare la chiave di flusso. Questo è suggerito nel caso in cui lo stesso IP possa essere visto utilizzando indirizzi MAC diversi (ad esempio un bilanciatore del carico).",
    ["toggle_use_mac_in_flow_key_title"] = "Utilizza l'indirizzo MAC in Flow Key",
    ["toggle_users_rrds_description"] = "Abilita la creazione di serie temporali per bytes e protocolli applicativi per gli utenti definiti.",
    ["toggle_users_rrds_title"] = "Utenti",
    ["toggle_vlan_rrds_description"] = "Abilita di serie temporali per traffico e protocolli applicativi per VLAN",
    ["toggle_vlan_rrds_title"] = "VLAN",
    ["toggle_wazuh_automerge_description"] = "Unisci automaticamente le informazioni sulle risorse Wazuh durante le ore notturne.",
    ["toggle_wazuh_automerge_title"] = "Unisci automaticamente le risorse Wazuh",
    ["toggle_wazuh_enabled_description"] = "Abilita l'integrazione Wazuh per configurare le impostazioni di connessione e correlare gli avvisi Wazuh con ntopng.",
    ["toggle_wazuh_enabled_title"] = "Abilita Wazuh",
    ["toggle_webhook_notification_description"] = "Abilita la notifica di allarmi via via webhook (HTTP).",
    ["toggle_webhook_notification_title"] = "Abilita Notifica Allarmi via Webhook",
    ["topics"] = "Argomenti",
    ["topk_heuristic_precision_description"] = "Abilita l'utilizzo di un'euristica quando si aggregano i principali host, i paesi, ecc., per creare report di traffico. Utile quando si creano report su lunghi periodi.",
    ["topk_heuristic_precision_title"] = "Euristica Top-K",
    ["traffic_behaviour"] = "Comportamento Traffico",
    ["traffic_bridging"] = "Traffic Bridging",
    ["traffic_shaping"] = "Shaping del Traffico",
    ["ts_and_stats_data_retention"] = "Conservazione dei dati di Serie Temporali/Statistiche",
    ["ts_and_stats_data_retention_descr"] = "Numero di giorni per conservare le serie temporali e le statistiche (ad es. Top Talkers). Predefinito: 30 giorni.<br><b>Nota:</b> se InfluxDB è attualmente utilizzato, per modificare correttamente i criteri di conservazione, è necessario il riavvio di ntopng.",
    ["ts_resolution_note2"] = "Abbassare la risoluzione puù creare gap nei dati esistenti. Si raccomanda <a target=_blank href=\"%{url}\">la cancellazione del database</a> %{external_icon}.",
